<?php
require_once __DIR__.'/includes/functions.php';must_login();require_permission('inventory');check_csrf();require_once __DIR__.'/config/database.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST')try{$pid=(int)$_POST['producto_id'];$tipo=$_POST['tipo'];$qty=(float)$_POST['cantidad'];$motivo=trim($_POST['motivo']);if($qty<=0)throw new RuntimeException('La cantidad debe ser mayor que cero.');$pdo->beginTransaction();$st=$pdo->prepare('SELECT stock FROM productos WHERE id=? FOR UPDATE');$st->execute([$pid]);$stock=$st->fetchColumn();if($stock===false)throw new RuntimeException('Producto no encontrado.');$tipo=$_POST['tipo']??'';if(!in_array($tipo,['Entrada','Salida','Ajuste'],true))throw new RuntimeException('Tipo de movimiento no válido.');$nuevo=$tipo==='Entrada'?$stock+$qty:($tipo==='Salida'?$stock-$qty:$qty);if($nuevo<0)throw new RuntimeException('No hay stock suficiente para esa salida.');$registrada=$tipo==='Ajuste'?abs($nuevo-$stock):$qty;$pdo->prepare('UPDATE productos SET stock=? WHERE id=?')->execute([$nuevo,$pid]);$pdo->prepare('INSERT INTO movimientos_inventario(producto_id,tipo,cantidad,motivo) VALUES(?,?,?,?)')->execute([$pid,$tipo,$registrada,$motivo]);$pdo->commit();flash('Movimiento de inventario registrado.');go('inventario.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException?'No se pudo registrar el movimiento.':$e->getMessage();}$products=$pdo->query('SELECT id,nombre,stock,unidad FROM productos WHERE estado="Activo" ORDER BY nombre')->fetchAll();$rows=$pdo->query('SELECT m.*,p.nombre producto,p.unidad FROM movimientos_inventario m JOIN productos p ON p.id=m.producto_id ORDER BY m.id DESC LIMIT 100')->fetchAll();$title='Control de inventario';require __DIR__.'/includes/header.php';?>
<div class="heading"><div><span class="eyebrow">ALMACÉN</span><h1>Control de inventario</h1><p class="muted">Registra entradas, salidas y ajustes de stock.</p></div></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="split"><section class="panel form-panel"><h2>Nuevo movimiento</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label class="field"><span>Producto</span><select name="producto_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['nombre'].' · disponible '.$p['stock'].' '.$p['unidad'])?></option><?php endforeach;?></select></label><label class="field"><span>Tipo</span><select name="tipo"><option>Entrada</option><option>Salida</option><option>Ajuste</option></select></label><label class="field"><span>Cantidad</span><input type="number" name="cantidad" min="0.01" step="0.01" required></label><label class="field"><span>Motivo</span><input name="motivo" required placeholder="Compra, merma, corrección..."></label><button class="btn">Registrar movimiento</button></form></section><section class="panel table-panel"><h2>Movimientos recientes</h2><div class="tablewrap"><table><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th>Cantidad</th><th>Motivo</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['fecha'])?></td><td><?=e($r['producto'])?></td><td><?=e($r['tipo'])?></td><td><?=e($r['cantidad'].' '.$r['unidad'])?></td><td><?=e($r['motivo'])?></td></tr><?php endforeach;?></table></div></section></div><?php require __DIR__.'/includes/footer.php';?>
